// Bài 11.4 — toggleTodo (đang sửa tại chỗ)
function toggleTodo(todos, id) {
  const t = todos.find((x) => x.id === id);
  if (t) t.done = !t.done;
  return todos;
}

solutionCodeJson.code:
// Bài 11.4 — toggleTodo bất biến: mảng mới, chỉ phần tử đổi là object mới
function toggleTodo(todos, id) {
  return todos.map((t) =>
    t.id === id ? { ...t, done: !t.done } : t   // không đổi ⇒ dùng lại đúng object cũ
  );
}

