// Bài 11.4 — setIn (đang sửa tại chỗ)
function setIn(obj, path, value) {
  let cur = obj;
  for (let i = 0; i < path.length - 1; i++) cur = cur[path[i]];
  cur[path[path.length - 1]] = value;
  return obj;
}

